export const screens = [{"id":"concept","title":"コンセプト","html":"<!doctype html><html><head><meta charset=\"utf-8\"></head><body><style> @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;500;700&family=Zen+Kaku+Gothic+New:wght@500;700;900&display=swap'); :root{ --bg:#0B0B0D; --surface:#151519; --surface2:#1E1E24; --line:rgba(255,255,255,.07); --tx:#ECECEA; --dim:#9A9AA2; --faint:#63636B; --gold:#CBA35A; --teal:#5FB0A5; --amber:#DB965A; --red:#D26A60; } *{box-sizing:border-box} body{margin:0;font-family:'Noto Sans JP',system-ui,sans-serif;background:var(--bg);color:var(--tx);-webkit-font-smoothing:antialiased} .disp{font-family:'Zen Kaku Gothic New','Noto Sans JP',sans-serif} a{color:var(--gold)} a:hover{color:#dcb877} .screen{width:390px;min-height:960px;position:relative; background:radial-gradient(120% 44% at 50% 0%, #1E1A22 0%, #0B0B0D 46%);padding:60px 26px 40px} .card{background:var(--surface);border:1px solid var(--line);border-radius:16px} </style><div class=\"screen\"><div class=\"disp\" style=\"font-weight:900;letter-spacing:.34em;font-size:14px;color:var(--gold);text-align:center\">PRIME</div><div style=\"font-size:11px;letter-spacing:.22em;color:var(--faint);text-align:center;margin-top:8px\">40歳からの代謝設計</div><!-- hero statement --><div class=\"disp\" style=\"font-size:29px;font-weight:900;line-height:1.5;text-align:center;margin:52px 0 18px\"> 40代からは<br><span style=\"color:var(--faint)\">「同じ努力」</span>では<br>もう<span style=\"background:linear-gradient(180deg,#F0D9A8,var(--gold));-webkit-background-clip:text;background-clip:text;color:transparent\">守れない。</span></div><div style=\"font-size:12.5px;color:var(--dim);text-align:center;line-height:1.9;margin-bottom:46px\"> 加齢で変わる身体の防衛本能を、<br>システム側でコントロールする。<br>根性ではなく、設計で結果を出す。 </div><!-- 4 pillars --><div style=\"display:flex;flex-direction:column;gap:12px;margin-bottom:40px\"><div class=\"card\" style=\"padding:15px 16px;display:flex;align-items:center;gap:13px\"><div style=\"width:36px;height:36px;border-radius:10px;background:rgba(210,106,96,.14);display:flex;align-items:center;justify-content:center;color:var(--red);flex:none\"><svg width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M6.5 6.5v11M17.5 6.5v11M3.5 9v6M20.5 9v6M6.5 12h11\"/></svg></div><div><div style=\"font-size:13.5px;font-weight:700\">アナボリック抵抗性</div><div style=\"font-size:11px;color:var(--dim);margin-top:2px\">鈍った筋肉を適正な刺激で押し切る</div></div></div><div class=\"card\" style=\"padding:15px 16px;display:flex;align-items:center;gap:13px\"><div style=\"width:36px;height:36px;border-radius:10px;background:rgba(219,150,90,.14);display:flex;align-items:center;justify-content:center;color:var(--amber);flex:none\"><svg width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M12 3l7 3v5c0 4.4-3 7.6-7 9-4-1.4-7-4.6-7-9V6z\"/><path d=\"M9 12l2 2 4-4\"/></svg></div><div><div style=\"font-size:13.5px;font-weight:700\">睡眠 × 筋肉保護</div><div style=\"font-size:11px;color:var(--dim);margin-top:2px\">睡眠不足の日は筋肉を削らせない</div></div></div><div class=\"card\" style=\"padding:15px 16px;display:flex;align-items:center;gap:13px\"><div style=\"width:36px;height:36px;border-radius:10px;background:rgba(203,163,90,.14);display:flex;align-items:center;justify-content:center;color:var(--gold);flex:none\"><svg width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-4 10.5c.7.7 1 1.4 1 2.5h6c0-1.1.3-1.8 1-2.5A6 6 0 0 0 12 3z\"/></svg></div><div><div style=\"font-size:13.5px;font-weight:700\">脳の省エネを打破</div><div style=\"font-size:11px;color:var(--dim);margin-top:2px\">無意識の活動量低下を行動で相殺</div></div></div><div class=\"card\" style=\"padding:15px 16px;display:flex;align-items:center;gap:13px\"><div style=\"width:36px;height:36px;border-radius:10px;background:rgba(95,176,165,.14);display:flex;align-items:center;justify-content:center;color:var(--teal);flex:none\"><svg width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 3c3 3 3 15 0 18M3 12h18\"/></svg></div><div><div style=\"font-size:13.5px;font-weight:700\">スポーツ連動</div><div style=\"font-size:11px;color:var(--dim);margin-top:2px\">テニス・ゴルフも有酸素として設計に統合</div></div></div></div><div style=\"background:linear-gradient(180deg,#E7CF97,var(--gold));color:#0B0B0D;text-align:center;font-family:'Zen Kaku Gothic New';font-weight:900;font-size:15px;padding:17px;border-radius:14px\"> 無料で体質診断を始める </div><div style=\"font-size:11px;color:var(--faint);text-align:center;margin-top:14px\">所要2分 ・ クレジットカード不要</div></div></body></html>"},{"id":"diagnosis","title":"診断結果","html":"<!doctype html><html><head><meta charset=\"utf-8\"></head><body><style> @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;500;700&family=Zen+Kaku+Gothic+New:wght@500;700;900&display=swap'); :root{ --bg:#0B0B0D; --surface:#151519; --surface2:#1E1E24; --line:rgba(255,255,255,.07); --tx:#ECECEA; --dim:#9A9AA2; --faint:#63636B; --gold:#CBA35A; --teal:#5FB0A5; --amber:#DB965A; --red:#D26A60; } *{box-sizing:border-box} body{margin:0;font-family:'Noto Sans JP',system-ui,sans-serif;background:var(--bg);color:var(--tx);-webkit-font-smoothing:antialiased} .disp{font-family:'Zen Kaku Gothic New','Noto Sans JP',sans-serif} a{color:var(--gold)} a:hover{color:#dcb877} .screen{width:390px;min-height:900px;position:relative; background:radial-gradient(130% 50% at 50% -6%, #1A1620 0%, #0B0B0D 50%); padding:24px 20px 40px} .card{background:var(--surface);border:1px solid var(--line);border-radius:16px} </style><div class=\"screen\"><!-- top bar --><div style=\"display:flex;align-items:center;gap:14px;margin-bottom:24px\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dim)\" stroke-width=\"1.9\"><path d=\"M15 5l-7 7 7 7\"/></svg><div style=\"font-size:11px;letter-spacing:.14em;color:var(--faint);text-transform:uppercase\">診断結果</div></div><!-- verdict --><div style=\"text-align:center;margin-bottom:22px\"><div style=\"font-size:12px;color:var(--dim);margin-bottom:8px\">あなたが痩せない主因は</div><div class=\"disp\" style=\"font-size:30px;font-weight:900;letter-spacing:.01em;line-height:1.25;background:linear-gradient(180deg,#F0D9A8,var(--gold));-webkit-background-clip:text;background-clip:text;color:transparent\"> アナボリック<br>抵抗性タイプ </div><div style=\"font-size:12.5px;color:var(--dim);margin-top:12px;line-height:1.7;max-width:300px;margin-left:auto;margin-right:auto\"> 40代以降、筋肉が刺激に反応しにくくなる状態。<br>「同じ努力」では筋肉が守れず、代謝が落ちています。 </div></div><!-- factor breakdown --><div style=\"font-size:12px;color:var(--faint);margin:0 2px 10px\">落ちない要因スコア</div><div class=\"card\" style=\"padding:18px 16px;margin-bottom:16px;display:flex;flex-direction:column;gap:16px\"><div><div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:7px\"><span style=\"font-size:13px;font-weight:700\">睡眠不足</span><span class=\"disp\" style=\"font-size:14px;font-weight:900;color:var(--red)\">82</span></div><div style=\"height:7px;background:#26262C;border-radius:4px\"><div style=\"width:82%;height:100%;background:var(--red);border-radius:4px\"></div></div></div><div><div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:7px\"><span style=\"font-size:13px;font-weight:700\">アナボリック抵抗性</span><span class=\"disp\" style=\"font-size:14px;font-weight:900;color:var(--red)\">76</span></div><div style=\"height:7px;background:#26262C;border-radius:4px\"><div style=\"width:76%;height:100%;background:var(--red);border-radius:4px\"></div></div></div><div><div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:7px\"><span style=\"font-size:13px;font-weight:700\">脳の省エネ (NEAT低下)</span><span class=\"disp\" style=\"font-size:14px;font-weight:900;color:var(--amber)\">64</span></div><div style=\"height:7px;background:#26262C;border-radius:4px\"><div style=\"width:64%;height:100%;background:var(--amber);border-radius:4px\"></div></div></div><div><div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:7px\"><span style=\"font-size:13px;font-weight:700\">たんぱく質不足</span><span class=\"disp\" style=\"font-size:14px;font-weight:900;color:var(--amber)\">51</span></div><div style=\"height:7px;background:#26262C;border-radius:4px\"><div style=\"width:51%;height:100%;background:var(--amber);border-radius:4px\"></div></div></div></div><!-- prescription --><div style=\"font-size:12px;color:var(--faint);margin:0 2px 10px\">あなた専用の処方</div><div style=\"display:flex;flex-direction:column;gap:10px;margin-bottom:24px\"><div class=\"card\" style=\"padding:14px 15px;display:flex;align-items:center;gap:12px\"><div style=\"width:34px;height:34px;border-radius:10px;background:rgba(95,176,165,.14);display:flex;align-items:center;justify-content:center;color:var(--teal);flex:none\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M3 12h4l2-6 4 12 2-6h6\"/></svg></div><div style=\"flex:1;font-size:12.5px;line-height:1.5\"><b>減量ペースを週0.5%に</b><br><span style=\"color:var(--dim)\">睡眠が整うまで筋肉を守る</span></div></div><div class=\"card\" style=\"padding:14px 15px;display:flex;align-items:center;gap:12px\"><div style=\"width:34px;height:34px;border-radius:10px;background:rgba(203,163,90,.14);display:flex;align-items:center;justify-content:center;color:var(--gold);flex:none\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M6.5 6.5v11M17.5 6.5v11M6.5 12h11\"/></svg></div><div style=\"flex:1;font-size:12.5px;line-height:1.5\"><b>各部位 週10〜20セット</b><br><span style=\"color:var(--dim)\">抵抗性を刺激で押し切る</span></div></div><div class=\"card\" style=\"padding:14px 15px;display:flex;align-items:center;gap:12px\"><div style=\"width:34px;height:34px;border-radius:10px;background:rgba(219,150,90,.14);display:flex;align-items:center;justify-content:center;color:var(--amber);flex:none\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M13 4l-2 8h5l-7 8 2-8H9z\"/></svg></div><div style=\"flex:1;font-size:12.5px;line-height:1.5\"><b>筋トレ日は +2,000歩</b><br><span style=\"color:var(--dim)\">脳の省エネを行動で相殺</span></div></div></div><!-- CTA --><div style=\"background:linear-gradient(180deg,#E7CF97,var(--gold));color:#0B0B0D;text-align:center;font-family:'Zen Kaku Gothic New';font-weight:900;font-size:15px;padding:16px;border-radius:14px\"> このプランで4週間の設計を作る </div></div></body></html>"},{"id":"home","title":"ホーム","html":"<!doctype html><html><head><meta charset=\"utf-8\"></head><body><style> @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;500;700&family=Zen+Kaku+Gothic+New:wght@500;700;900&display=swap'); :root{ --bg:#0B0B0D; --surface:#151519; --surface2:#1E1E24; --line:rgba(255,255,255,.07); --tx:#ECECEA; --dim:#9A9AA2; --faint:#63636B; --gold:#CBA35A; --teal:#5FB0A5; --amber:#DB965A; --red:#D26A60; } *{box-sizing:border-box} body{margin:0;font-family:'Noto Sans JP',system-ui,sans-serif;background:var(--bg);color:var(--tx);-webkit-font-smoothing:antialiased} .disp{font-family:'Zen Kaku Gothic New','Noto Sans JP',sans-serif} a{color:var(--gold)} a:hover{color:#dcb877} .screen{width:390px;min-height:900px;position:relative; background:radial-gradient(130% 55% at 50% -8%, #18181E 0%, #0B0B0D 52%); padding:26px 20px 96px} .card{background:var(--surface);border:1px solid var(--line);border-radius:18px} .wm{font-family:'Zen Kaku Gothic New';font-weight:900;letter-spacing:.32em;font-size:13px;color:var(--gold)} .eyebrow{font-size:11px;letter-spacing:.14em;color:var(--faint);text-transform:uppercase} </style><div class=\"screen\"><!-- header --><div style=\"display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:22px\"><div><div class=\"wm\">PRIME</div><div style=\"margin-top:10px;font-size:12px;color:var(--dim)\">8月24日 (月)</div><div class=\"disp\" style=\"font-size:20px;font-weight:700;margin-top:2px\">おはようございます、Ken さん</div></div><div style=\"width:42px;height:42px;border-radius:50%;border:1px solid var(--line);background:var(--surface2);display:flex;align-items:center;justify-content:center;color:var(--dim)\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"><circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 20c0-4 3.6-6 8-6s8 2 8 6\"/></svg></div></div><!-- muscle protection status --><div class=\"card\" style=\"padding:16px 16px 15px;border-color:rgba(219,150,90,.35);background:linear-gradient(180deg,rgba(219,150,90,.10),var(--surface));margin-bottom:16px\"><div style=\"display:flex;align-items:center;gap:11px\"><div style=\"width:34px;height:34px;border-radius:10px;background:rgba(219,150,90,.16);display:flex;align-items:center;justify-content:center;color:var(--amber);flex:none\"><svg width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M12 3l7 3v5c0 4.4-3 7.6-7 9-4-1.4-7-4.6-7-9V6z\"/><path d=\"M9 12l2 2 4-4\"/></svg></div><div style=\"flex:1\"><div style=\"display:flex;align-items:center;gap:8px\"><span class=\"disp\" style=\"font-weight:700;font-size:15px\">筋肉保護モード</span><span style=\"font-size:10px;font-weight:700;letter-spacing:.08em;color:#0B0B0D;background:var(--amber);padding:2px 7px;border-radius:6px\">ON</span></div><div style=\"font-size:11.5px;color:var(--dim);margin-top:3px;line-height:1.5\">睡眠 5時間32分を検知。減量ペースを <b style=\"color:var(--tx)\">週 0.5%</b> に自動調整しました。</div></div></div></div><!-- today's plan --><div style=\"display:flex;align-items:baseline;justify-content:space-between;margin:0 2px 10px\"><div class=\"disp\" style=\"font-size:16px;font-weight:700\">今日のプラン</div><div style=\"font-size:11px;color:var(--faint)\">コンカレント順</div></div><div class=\"card\" style=\"padding:6px 4px;margin-bottom:16px\"><!-- step 1 strength --><div style=\"display:flex;align-items:center;gap:13px;padding:13px 14px\"><div style=\"width:40px;height:40px;border-radius:12px;background:rgba(203,163,90,.14);display:flex;align-items:center;justify-content:center;color:var(--gold);flex:none\"><svg width=\"21\" height=\"21\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M6.5 6.5v11M17.5 6.5v11M3.5 9v6M20.5 9v6M6.5 12h11\"/></svg></div><div style=\"flex:1\"><div style=\"font-weight:700;font-size:14px\">① 筋トレ ・ 胸 / 三頭</div><div style=\"font-size:11.5px;color:var(--dim);margin-top:2px\">45分 ・ 6種目 ・ RIR 1〜2</div></div><div style=\"font-size:11px;font-weight:700;color:var(--gold);border:1px solid rgba(203,163,90,.4);padding:6px 11px;border-radius:9px\">開始</div></div><div style=\"height:1px;background:var(--line);margin:0 14px\"></div><!-- step 2 cardio locked --><div style=\"display:flex;align-items:center;gap:13px;padding:13px 14px;opacity:.62\"><div style=\"width:40px;height:40px;border-radius:12px;background:var(--surface2);display:flex;align-items:center;justify-content:center;color:var(--dim);flex:none\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><circle cx=\"12\" cy=\"8\" r=\"6\"/><rect x=\"9\" y=\"10.5\" width=\"6\" height=\"5\" rx=\"1.4\"/></svg></div><div style=\"flex:1\"><div style=\"font-weight:700;font-size:14px\">② 有酸素 ・ 25分</div><div style=\"font-size:11.5px;color:var(--faint);margin-top:2px\">筋トレ完了で解放されます</div></div><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--faint)\" stroke-width=\"1.8\"><rect x=\"5\" y=\"11\" width=\"14\" height=\"9\" rx=\"2\"/><path d=\"M8 11V8a4 4 0 0 1 8 0v3\"/></svg></div></div><!-- NEAT + volume row --><div style=\"display:flex;gap:12px;margin-bottom:16px\"><!-- NEAT ring --><div class=\"card\" style=\"flex:1;padding:16px 14px;text-align:center\"><div style=\"position:relative;width:96px;height:96px;margin:2px auto 0\"><svg width=\"96\" height=\"96\" viewBox=\"0 0 96 96\"><circle cx=\"48\" cy=\"48\" r=\"40\" fill=\"none\" stroke=\"#26262C\" stroke-width=\"8\"/><circle cx=\"48\" cy=\"48\" r=\"40\" fill=\"none\" stroke=\"var(--teal)\" stroke-width=\"8\" stroke-linecap=\"round\" stroke-dasharray=\"251.2\" stroke-dashoffset=\"59\" transform=\"rotate(-90 48 48)\"/></svg><div style=\"position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center\"><div class=\"disp\" style=\"font-size:22px;font-weight:900;line-height:1\">6,120</div><div style=\"font-size:10px;color:var(--faint)\">/ 8,000 歩</div></div></div><div style=\"margin-top:11px;font-size:11px;font-weight:700;color:var(--amber);background:rgba(219,150,90,.12);display:inline-block;padding:4px 9px;border-radius:7px\">筋トレ日・厳格監視</div></div><!-- weekly volume --><div class=\"card\" style=\"flex:1;padding:16px 15px\"><div style=\"font-size:12px;color:var(--dim);margin-bottom:2px\">週間ボリューム</div><div style=\"font-size:10px;color:var(--faint);margin-bottom:14px\">目標 10〜20 set</div><div style=\"display:flex;flex-direction:column;gap:13px\"><div><div style=\"display:flex;justify-content:space-between;font-size:11px;margin-bottom:5px\"><span>胸</span><span style=\"color:var(--teal)\">14</span></div><div style=\"height:6px;background:#26262C;border-radius:3px\"><div style=\"width:78%;height:100%;background:var(--teal);border-radius:3px\"></div></div></div><div><div style=\"display:flex;justify-content:space-between;font-size:11px;margin-bottom:5px\"><span>背中</span><span style=\"color:var(--teal)\">16</span></div><div style=\"height:6px;background:#26262C;border-radius:3px\"><div style=\"width:88%;height:100%;background:var(--teal);border-radius:3px\"></div></div></div><div><div style=\"display:flex;justify-content:space-between;font-size:11px;margin-bottom:5px\"><span>脚</span><span style=\"color:var(--amber)\">7</span></div><div style=\"height:6px;background:#26262C;border-radius:3px\"><div style=\"width:38%;height:100%;background:var(--amber);border-radius:3px\"></div></div></div></div></div></div><!-- bottom nav --><div style=\"position:absolute;left:0;right:0;bottom:0;height:74px;background:rgba(12,12,14,.92);backdrop-filter:blur(12px);border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-around;padding:0 8px 14px\"><div style=\"display:flex;flex-direction:column;align-items:center;gap:5px;color:var(--gold)\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M4 11l8-7 8 7\"/><path d=\"M6 10v9h12v-9\"/></svg><span style=\"font-size:9.5px;font-weight:700\">ホーム</span></div><div style=\"display:flex;flex-direction:column;align-items:center;gap:5px;color:var(--faint)\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><rect x=\"4\" y=\"5\" width=\"16\" height=\"16\" rx=\"2\"/><path d=\"M4 9h16M8 3v4M16 3v4\"/></svg><span style=\"font-size:9.5px\">プラン</span></div><div style=\"display:flex;flex-direction:column;align-items:center;gap:5px;color:var(--faint)\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M6.5 6.5v11M17.5 6.5v11M3.5 9v6M20.5 9v6M6.5 12h11\"/></svg><span style=\"font-size:9.5px\">記録</span></div><div style=\"display:flex;flex-direction:column;align-items:center;gap:5px;color:var(--faint)\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M4 19V5M4 19h16M8 16v-5M12 16V8M16 16v-3\"/></svg><span style=\"font-size:9.5px\">分析</span></div><div style=\"display:flex;flex-direction:column;align-items:center;gap:5px;color:var(--faint)\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 20c0-4 3.6-6 8-6s8 2 8 6\"/></svg><span style=\"font-size:9.5px\">マイ</span></div></div></div></body></html>"},{"id":"session","title":"セッション","html":"<!doctype html><html><head><meta charset=\"utf-8\"></head><body><style> @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;500;700&family=Zen+Kaku+Gothic+New:wght@500;700;900&display=swap'); :root{ --bg:#0B0B0D; --surface:#151519; --surface2:#1E1E24; --line:rgba(255,255,255,.07); --tx:#ECECEA; --dim:#9A9AA2; --faint:#63636B; --gold:#CBA35A; --teal:#5FB0A5; --amber:#DB965A; --red:#D26A60; } *{box-sizing:border-box} body{margin:0;font-family:'Noto Sans JP',system-ui,sans-serif;background:var(--bg);color:var(--tx);-webkit-font-smoothing:antialiased} .disp{font-family:'Zen Kaku Gothic New','Noto Sans JP',sans-serif} a{color:var(--gold)} a:hover{color:#dcb877} .screen{width:390px;min-height:900px;position:relative; background:radial-gradient(130% 50% at 50% -6%, #18181E 0%, #0B0B0D 50%);padding:24px 20px 40px} .card{background:var(--surface);border:1px solid var(--line);border-radius:16px} .tick{width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex:none} </style><div class=\"screen\"><div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:20px\"><div style=\"display:flex;align-items:center;gap:14px\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dim)\" stroke-width=\"1.9\"><path d=\"M15 5l-7 7 7 7\"/></svg><div class=\"disp\" style=\"font-size:18px;font-weight:700\">本日のセッション</div></div><div style=\"font-size:12px;color:var(--gold);font-weight:700\">28:14</div></div><!-- concurrent order banner --><div class=\"card\" style=\"padding:12px 14px;margin-bottom:18px;display:flex;align-items:center;gap:10px;border-color:rgba(203,163,90,.28)\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--gold)\" stroke-width=\"1.9\"><path d=\"M13 2L4.5 13H11l-1 9 8.5-11H12z\"/></svg><div style=\"font-size:11.5px;color:var(--dim);line-height:1.5\">脂肪燃焼の黄金順序 — <b style=\"color:var(--tx)\">筋トレ → 有酸素</b> でロックされています</div></div><!-- STRENGTH block --><div style=\"display:flex;align-items:center;justify-content:space-between;margin:0 2px 12px\"><span class=\"disp\" style=\"font-size:14px;font-weight:700;color:var(--gold)\">① 筋トレ ・ 胸 / 三頭</span><span style=\"font-size:12px;color:var(--dim)\">3 / 6 種目</span></div><div style=\"height:6px;background:#26262C;border-radius:3px;margin:0 2px 16px\"><div style=\"width:50%;height:100%;background:linear-gradient(90deg,var(--gold),#E7CF97);border-radius:3px\"></div></div><div class=\"card\" style=\"padding:6px 4px;margin-bottom:20px\"><!-- done --><div style=\"display:flex;align-items:center;gap:13px;padding:12px 14px\"><div class=\"tick\" style=\"background:var(--teal)\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#0B0B0D\" stroke-width=\"2.6\"><path d=\"M5 12l4 4 10-11\"/></svg></div><div style=\"flex:1\"><div style=\"font-size:13.5px;font-weight:700\">ベンチプレス</div><div style=\"font-size:11px;color:var(--faint);margin-top:1px\">62.5kg × 8,8,7 ・ RIR 1</div></div></div><div style=\"height:1px;background:var(--line);margin:0 14px\"></div><div style=\"display:flex;align-items:center;gap:13px;padding:12px 14px\"><div class=\"tick\" style=\"background:var(--teal)\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#0B0B0D\" stroke-width=\"2.6\"><path d=\"M5 12l4 4 10-11\"/></svg></div><div style=\"flex:1\"><div style=\"font-size:13.5px;font-weight:700\">インクラインDBプレス</div><div style=\"font-size:11px;color:var(--faint);margin-top:1px\">22kg × 10,9,9 ・ RIR 2</div></div></div><div style=\"height:1px;background:var(--line);margin:0 14px\"></div><!-- active --><div style=\"display:flex;align-items:center;gap:13px;padding:14px;background:rgba(203,163,90,.07);border-radius:12px;margin:2px 4px\"><div class=\"tick\" style=\"border:2px solid var(--gold);color:var(--gold);font-weight:800;font-size:12px\" class=\"disp\">3</div><div style=\"flex:1\"><div style=\"font-size:13.5px;font-weight:700\">ケーブルフライ</div><div style=\"font-size:11px;color:var(--gold);margin-top:1px\">推奨 15kg ・ 3セット目</div></div><div style=\"font-size:11px;font-weight:700;color:#0B0B0D;background:var(--gold);padding:7px 13px;border-radius:9px\">記録</div></div><div style=\"height:1px;background:var(--line);margin:0 14px\"></div><!-- upcoming --><div style=\"display:flex;align-items:center;gap:13px;padding:12px 14px;opacity:.55\"><div class=\"tick\" style=\"border:2px solid #3A3A42;color:var(--faint);font-weight:700;font-size:12px\">4</div><div style=\"flex:1\"><div style=\"font-size:13.5px;font-weight:700\">トライセプスプレスダウン</div></div></div><div style=\"display:flex;align-items:center;gap:13px;padding:12px 14px;opacity:.55\"><div class=\"tick\" style=\"border:2px solid #3A3A42;color:var(--faint);font-weight:700;font-size:12px\">5</div><div style=\"flex:1\"><div style=\"font-size:13.5px;font-weight:700\">オーバーヘッドエクステンション</div></div></div></div><!-- CARDIO locked --><div class=\"card\" style=\"padding:20px 18px;text-align:center;border-style:dashed;border-color:rgba(255,255,255,.12);background:var(--surface2)\"><div style=\"width:46px;height:46px;border-radius:14px;background:rgba(255,255,255,.05);display:flex;align-items:center;justify-content:center;margin:0 auto 12px\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--faint)\" stroke-width=\"1.8\"><rect x=\"5\" y=\"11\" width=\"14\" height=\"9\" rx=\"2\"/><path d=\"M8 11V8a4 4 0 0 1 8 0v3\"/></svg></div><div class=\"disp\" style=\"font-size:15px;font-weight:700;color:var(--dim)\">② 有酸素 ・ 25分</div><div style=\"font-size:11.5px;color:var(--faint);margin-top:6px;line-height:1.6\">筋トレ6種目を完了すると<br>有酸素タイマーが自動で起動します</div></div></div></body></html>"},{"id":"rir","title":"RIR記録","html":"<!doctype html><html><head><meta charset=\"utf-8\"></head><body><style> @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;500;700&family=Zen+Kaku+Gothic+New:wght@500;700;900&display=swap'); :root{ --bg:#0B0B0D; --surface:#151519; --surface2:#1E1E24; --line:rgba(255,255,255,.07); --tx:#ECECEA; --dim:#9A9AA2; --faint:#63636B; --gold:#CBA35A; --teal:#5FB0A5; --amber:#DB965A; --red:#D26A60; } *{box-sizing:border-box} body{margin:0;font-family:'Noto Sans JP',system-ui,sans-serif;background:var(--bg);color:var(--tx);-webkit-font-smoothing:antialiased} .disp{font-family:'Zen Kaku Gothic New','Noto Sans JP',sans-serif} a{color:var(--gold)} a:hover{color:#dcb877} .screen{width:390px;min-height:900px;position:relative; background:radial-gradient(130% 50% at 50% -6%, #18181E 0%, #0B0B0D 50%);padding:24px 20px 40px} .card{background:var(--surface);border:1px solid var(--line);border-radius:16px} </style><div class=\"screen\"><div style=\"display:flex;align-items:center;gap:14px;margin-bottom:20px\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dim)\" stroke-width=\"1.9\"><path d=\"M15 5l-7 7 7 7\"/></svg><div class=\"disp\" style=\"font-size:18px;font-weight:700\">ケーブルフライ</div></div><!-- weight & reps input --><div style=\"display:flex;gap:12px;margin-bottom:18px\"><div class=\"card\" style=\"flex:1;padding:16px 14px;text-align:center\"><div style=\"font-size:11px;color:var(--faint);margin-bottom:6px\">重量 (kg)</div><div class=\"disp\" style=\"font-size:30px;font-weight:900;color:var(--gold)\">15.0</div></div><div class=\"card\" style=\"flex:1;padding:16px 14px;text-align:center\"><div style=\"font-size:11px;color:var(--faint);margin-bottom:6px\">回数</div><div class=\"disp\" style=\"font-size:30px;font-weight:900\">12</div></div></div><!-- RIR slider --><div class=\"card\" style=\"padding:18px 18px 20px;margin-bottom:16px\"><div style=\"display:flex;align-items:baseline;justify-content:space-between;margin-bottom:4px\"><span style=\"font-size:13px;font-weight:700\">RIR ・ あと何回できた？</span></div><div style=\"font-size:11px;color:var(--dim);margin-bottom:20px\">適正ゾーンは <b style=\"color:var(--gold)\">1〜2回</b>。限界まで追い込みすぎず、筋肉を効かせます。</div><!-- track --><div style=\"position:relative;height:44px\"><!-- zone highlight --><div style=\"position:absolute;top:17px;height:8px;left:20%;width:20%;background:rgba(203,163,90,.28);border-radius:4px\"></div><div style=\"position:absolute;top:20px;left:0;right:0;height:3px;background:#2A2A31;border-radius:2px\"></div><div style=\"position:absolute;top:20px;left:0;width:32%;height:3px;background:var(--gold);border-radius:2px\"></div><!-- thumb at RIR 1 (~32%) --><div style=\"position:absolute;top:8px;left:calc(32% - 13px);width:26px;height:26px;border-radius:50%;background:var(--gold);box-shadow:0 2px 10px rgba(203,163,90,.5);border:3px solid #0B0B0D\"></div></div><div style=\"display:flex;justify-content:space-between;margin-top:6px;font-size:11px;color:var(--faint)\"><span>0<br><span style=\"font-size:9px\">限界</span></span><span style=\"color:var(--gold);font-weight:700\">1</span><span style=\"color:var(--gold);font-weight:700\">2</span><span>3</span><span>4+<br><span style=\"font-size:9px\">余裕</span></span></div></div><!-- learned recommendation --><div class=\"card\" style=\"padding:16px;margin-bottom:16px;border-color:rgba(95,176,165,.3);background:linear-gradient(180deg,rgba(95,176,165,.08),var(--surface))\"><div style=\"display:flex;align-items:center;gap:10px\"><div style=\"width:32px;height:32px;border-radius:9px;background:rgba(95,176,165,.16);display:flex;align-items:center;justify-content:center;color:var(--teal);flex:none\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M12 3v3M12 18v3M3 12h3M18 12h3M6 6l2 2M16 16l2 2M18 6l-2 2M8 16l-2 2\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></div><div style=\"flex:1;font-size:12.5px;line-height:1.5\">RIR履歴を学習しました。<br><span style=\"color:var(--dim)\">次回の推奨は </span><b style=\"color:var(--teal)\">17.5kg</b><span style=\"color:var(--dim)\"> です</span></div></div></div><!-- history row --><div style=\"font-size:12px;color:var(--faint);margin:0 2px 10px\">このセットの記録</div><div class=\"card\" style=\"padding:6px 4px;margin-bottom:22px\"><div style=\"display:flex;align-items:center;padding:11px 14px;font-size:12.5px\"><span style=\"width:52px;color:var(--faint)\">Set 1</span><span style=\"flex:1\">15kg × 12</span><span style=\"color:var(--gold);font-weight:700\">RIR 2</span></div><div style=\"height:1px;background:var(--line);margin:0 14px\"></div><div style=\"display:flex;align-items:center;padding:11px 14px;font-size:12.5px\"><span style=\"width:52px;color:var(--faint)\">Set 2</span><span style=\"flex:1\">15kg × 12</span><span style=\"color:var(--gold);font-weight:700\">RIR 1</span></div><div style=\"height:1px;background:var(--line);margin:0 14px\"></div><div style=\"display:flex;align-items:center;padding:11px 14px;font-size:12.5px;opacity:.6\"><span style=\"width:52px;color:var(--faint)\">Set 3</span><span style=\"flex:1;color:var(--dim)\">入力中…</span></div></div><div style=\"background:linear-gradient(180deg,#E7CF97,var(--gold));color:#0B0B0D;text-align:center;font-family:'Zen Kaku Gothic New';font-weight:900;font-size:15px;padding:16px;border-radius:14px\"> このセットを記録 </div></div></body></html>"},{"id":"sleep","title":"睡眠保護","html":"<!doctype html><html><head><meta charset=\"utf-8\"></head><body><style> @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;500;700&family=Zen+Kaku+Gothic+New:wght@500;700;900&display=swap'); :root{ --bg:#0B0B0D; --surface:#151519; --surface2:#1E1E24; --line:rgba(255,255,255,.07); --tx:#ECECEA; --dim:#9A9AA2; --faint:#63636B; --gold:#CBA35A; --teal:#5FB0A5; --amber:#DB965A; --red:#D26A60; } *{box-sizing:border-box} body{margin:0;font-family:'Noto Sans JP',system-ui,sans-serif;background:var(--bg);color:var(--tx);-webkit-font-smoothing:antialiased} .disp{font-family:'Zen Kaku Gothic New','Noto Sans JP',sans-serif} a{color:var(--gold)} a:hover{color:#dcb877} .screen{width:390px;min-height:900px;position:relative; background:radial-gradient(130% 52% at 50% -6%, #14161C 0%, #0B0B0D 52%);padding:24px 20px 40px} .card{background:var(--surface);border:1px solid var(--line);border-radius:16px} </style><div class=\"screen\"><div style=\"display:flex;align-items:center;gap:14px;margin-bottom:22px\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dim)\" stroke-width=\"1.9\"><path d=\"M15 5l-7 7 7 7\"/></svg><div class=\"disp\" style=\"font-size:18px;font-weight:700\">筋肉保護アルゴリズム</div></div><!-- alert --><div class=\"card\" style=\"padding:18px 16px;margin-bottom:18px;border-color:rgba(219,150,90,.4);background:linear-gradient(180deg,rgba(219,150,90,.12),var(--surface))\"><div style=\"display:flex;align-items:center;gap:10px;margin-bottom:10px\"><div style=\"width:32px;height:32px;border-radius:9px;background:rgba(219,150,90,.18);display:flex;align-items:center;justify-content:center;color:var(--amber)\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\"><path d=\"M12 4v8M12 16v.5\"/><path d=\"M12 3l9 16H3z\"/></svg></div><div class=\"disp\" style=\"font-size:15px;font-weight:700\">睡眠不足を3日連続で検知</div></div><div style=\"font-size:12px;color:var(--dim);line-height:1.7\"> 睡眠不足下の減量は、脂肪ではなく<b style=\"color:var(--tx)\">筋肉から</b>削られます。あなたの身体を守るため、目標を自動調整しました。 </div></div><!-- 7 day sleep chart --><div class=\"card\" style=\"padding:18px 16px 16px;margin-bottom:18px\"><div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:18px\"><span style=\"font-size:13px;font-weight:700\">睡眠時間 ・ 7日間</span><span style=\"font-size:11px;color:var(--faint)\">基準ライン 6h</span></div><div style=\"position:relative;height:118px\"><!-- threshold line --><div style=\"position:absolute;left:0;right:0;top:34px;border-top:1px dashed rgba(219,150,90,.55)\"></div><div style=\"position:absolute;right:0;top:22px;font-size:9px;color:var(--amber)\">6h</div><div style=\"display:flex;align-items:flex-end;justify-content:space-between;height:100%;gap:8px\"><!-- each bar: max height 100 = ~8h; 6h line at 34px from top = value75 --><div style=\"flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%\"><div style=\"width:100%;height:88%;background:var(--teal);border-radius:5px 5px 0 0\"></div></div><div style=\"flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%\"><div style=\"width:100%;height:80%;background:var(--teal);border-radius:5px 5px 0 0\"></div></div><div style=\"flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%\"><div style=\"width:100%;height:70%;background:var(--teal);border-radius:5px 5px 0 0\"></div></div><div style=\"flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%\"><div style=\"width:100%;height:62%;background:var(--amber);border-radius:5px 5px 0 0\"></div></div><div style=\"flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%\"><div style=\"width:100%;height:58%;background:var(--amber);border-radius:5px 5px 0 0\"></div></div><div style=\"flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%\"><div style=\"width:100%;height:52%;background:var(--red);border-radius:5px 5px 0 0\"></div></div></div></div><div style=\"display:flex;justify-content:space-between;margin-top:8px;font-size:10px;color:var(--faint)\"><span style=\"flex:1;text-align:center\">火</span><span style=\"flex:1;text-align:center\">水</span><span style=\"flex:1;text-align:center\">木</span><span style=\"flex:1;text-align:center\">金</span><span style=\"flex:1;text-align:center\">土</span><span style=\"flex:1;text-align:center\">日</span></div></div><!-- auto adjustment --><div style=\"font-size:12px;color:var(--faint);margin:0 2px 10px\">自動調整の内容</div><div class=\"card\" style=\"padding:6px 4px;margin-bottom:16px\"><div style=\"display:flex;align-items:center;gap:12px;padding:14px\"><div style=\"flex:1;font-size:13px\">減量ペース</div><div style=\"display:flex;align-items:center;gap:9px\"><span style=\"font-size:12px;color:var(--faint);text-decoration:line-through\">週1.0%</span><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--faint)\" stroke-width=\"2\"><path d=\"M5 12h13M13 6l6 6-6 6\"/></svg><span class=\"disp\" style=\"font-size:14px;font-weight:800;color:var(--teal)\">週0.5%</span></div></div><div style=\"height:1px;background:var(--line);margin:0 14px\"></div><div style=\"display:flex;align-items:center;gap:12px;padding:14px\"><div style=\"flex:1;font-size:13px\">本日の優先</div><div style=\"display:flex;align-items:center;gap:9px\"><span style=\"font-size:12px;color:var(--faint);text-decoration:line-through\">有酸素</span><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--faint)\" stroke-width=\"2\"><path d=\"M5 12h13M13 6l6 6-6 6\"/></svg><span class=\"disp\" style=\"font-size:14px;font-weight:800;color:var(--gold)\">筋トレ</span></div></div><div style=\"height:1px;background:var(--line);margin:0 14px\"></div><div style=\"display:flex;align-items:center;gap:12px;padding:14px\"><div style=\"flex:1;font-size:13px\">たんぱく質目標</div><div style=\"display:flex;align-items:center;gap:9px\"><span style=\"font-size:12px;color:var(--faint);text-decoration:line-through\">112g</span><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--faint)\" stroke-width=\"2\"><path d=\"M5 12h13M13 6l6 6-6 6\"/></svg><span class=\"disp\" style=\"font-size:14px;font-weight:800;color:var(--teal)\">128g</span></div></div></div><div style=\"font-size:11px;color:var(--faint);text-align:center;line-height:1.7;padding:0 8px\"> 睡眠が2日連続で7時間を超えると、<br>通常の減量ペースへ自動で戻します。 </div></div></body></html>"},{"id":"neat","title":"NEAT","html":"<!doctype html><html><head><meta charset=\"utf-8\"></head><body><style> @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;500;700&family=Zen+Kaku+Gothic+New:wght@500;700;900&display=swap'); :root{ --bg:#0B0B0D; --surface:#151519; --surface2:#1E1E24; --line:rgba(255,255,255,.07); --tx:#ECECEA; --dim:#9A9AA2; --faint:#63636B; --gold:#CBA35A; --teal:#5FB0A5; --amber:#DB965A; --red:#D26A60; } *{box-sizing:border-box} body{margin:0;font-family:'Noto Sans JP',system-ui,sans-serif;background:var(--bg);color:var(--tx);-webkit-font-smoothing:antialiased} .disp{font-family:'Zen Kaku Gothic New','Noto Sans JP',sans-serif} a{color:var(--gold)} a:hover{color:#dcb877} .screen{width:390px;min-height:900px;position:relative; background:radial-gradient(130% 50% at 50% -6%, #18181E 0%, #0B0B0D 50%);padding:24px 20px 40px} .card{background:var(--surface);border:1px solid var(--line);border-radius:16px} </style><div class=\"screen\"><div style=\"display:flex;align-items:center;gap:14px;margin-bottom:20px\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dim)\" stroke-width=\"1.9\"><path d=\"M15 5l-7 7 7 7\"/></svg><div class=\"disp\" style=\"font-size:18px;font-weight:700\">脳のサボり打破</div></div><!-- push notification mock --><div style=\"background:rgba(30,30,36,.86);backdrop-filter:blur(14px);border:1px solid rgba(255,255,255,.1);border-radius:18px;padding:14px 15px;margin-bottom:20px;box-shadow:0 12px 30px rgba(0,0,0,.5)\"><div style=\"display:flex;align-items:center;gap:9px;margin-bottom:9px\"><div style=\"width:20px;height:20px;border-radius:5px;background:var(--gold);display:flex;align-items:center;justify-content:center\"><span class=\"disp\" style=\"font-size:9px;font-weight:900;color:#0B0B0D\">P</span></div><span style=\"font-size:11px;font-weight:700;letter-spacing:.14em;color:var(--dim)\">PRIME</span><span style=\"font-size:11px;color:var(--faint);margin-left:auto\">今</span></div><div style=\"font-size:13px;font-weight:700;margin-bottom:4px\">身体が省エネモードに入っています ⚠</div><div style=\"font-size:12px;color:var(--dim);line-height:1.55\">今日は筋トレをしたため、無意識に活動量が落ちています。目標 8,000歩まで <b style=\"color:var(--tx)\">あと 1,880歩</b>。夕方の散歩で相殺しましょう。</div></div><!-- explainer --><div class=\"card\" style=\"padding:15px 16px;margin-bottom:18px;display:flex;gap:11px;align-items:flex-start\"><div style=\"width:30px;height:30px;border-radius:9px;background:rgba(219,150,90,.14);display:flex;align-items:center;justify-content:center;color:var(--amber);flex:none;margin-top:1px\"><svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-4 10.5c.7.7 1 1.4 1 2.5h6c0-1.1.3-1.8 1-2.5A6 6 0 0 0 12 3z\"/></svg></div><div style=\"font-size:11.5px;color:var(--dim);line-height:1.65\">運動した日ほど、脳が家事や歩行を無意識に減らして消費カロリーを<b style=\"color:var(--tx)\">相殺</b>します。筋トレ日は歩数を通常より厳しく監視します。</div></div><!-- step progress --><div class=\"card\" style=\"padding:20px 18px 18px;margin-bottom:18px;text-align:center\"><div class=\"disp\" style=\"font-size:40px;font-weight:900;line-height:1;color:var(--amber)\">6,120</div><div style=\"font-size:12px;color:var(--faint);margin-top:4px\">/ 8,000 歩 ・ 筋トレ日目標</div><div style=\"height:9px;background:#26262C;border-radius:5px;margin:16px 0 6px;overflow:hidden\"><div style=\"width:76.5%;height:100%;background:linear-gradient(90deg,var(--amber),#E7BB86);border-radius:5px\"></div></div><div style=\"font-size:11px;color:var(--amber);font-weight:700\">あと 1,880歩</div></div><!-- hourly activity --><div class=\"card\" style=\"padding:16px 16px 14px\"><div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:16px\"><span style=\"font-size:13px;font-weight:700\">時間帯別の活動量</span><span style=\"font-size:11px;color:var(--red)\">14時以降に低下 ↓</span></div><div style=\"display:flex;align-items:flex-end;justify-content:space-between;height:76px;gap:5px\"><div style=\"flex:1;height:40%;background:var(--teal);border-radius:3px\"></div><div style=\"flex:1;height:62%;background:var(--teal);border-radius:3px\"></div><div style=\"flex:1;height:88%;background:var(--teal);border-radius:3px\"></div><div style=\"flex:1;height:74%;background:var(--teal);border-radius:3px\"></div><div style=\"flex:1;height:30%;background:var(--amber);border-radius:3px\"></div><div style=\"flex:1;height:20%;background:var(--red);border-radius:3px\"></div><div style=\"flex:1;height:16%;background:var(--red);border-radius:3px\"></div><div style=\"flex:1;height:22%;background:#3A3A42;border-radius:3px\"></div></div><div style=\"display:flex;justify-content:space-between;margin-top:7px;font-size:9.5px;color:var(--faint)\"><span style=\"flex:1;text-align:center\">8</span><span style=\"flex:1;text-align:center\">10</span><span style=\"flex:1;text-align:center\">12</span><span style=\"flex:1;text-align:center\">14</span><span style=\"flex:1;text-align:center\">16</span><span style=\"flex:1;text-align:center\">18</span><span style=\"flex:1;text-align:center\">20</span><span style=\"flex:1;text-align:center\">22</span></div></div></div></body></html>"},{"id":"sports","title":"スポーツ連動","html":"<!doctype html><html><head><meta charset=\"utf-8\"></head><body><style> @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;500;700&family=Zen+Kaku+Gothic+New:wght@500;700;900&display=swap'); :root{ --bg:#0B0B0D; --surface:#151519; --surface2:#1E1E24; --line:rgba(255,255,255,.07); --tx:#ECECEA; --dim:#9A9AA2; --faint:#63636B; --gold:#CBA35A; --teal:#5FB0A5; --amber:#DB965A; --red:#D26A60; } *{box-sizing:border-box} body{margin:0;font-family:'Noto Sans JP',system-ui,sans-serif;background:var(--bg);color:var(--tx);-webkit-font-smoothing:antialiased} .disp{font-family:'Zen Kaku Gothic New','Noto Sans JP',sans-serif} a{color:var(--gold)} a:hover{color:#dcb877} .screen{width:390px;min-height:960px;position:relative; background:radial-gradient(130% 50% at 50% -6%, #14181C 0%, #0B0B0D 52%);padding:24px 20px 40px} .card{background:var(--surface);border:1px solid var(--line);border-radius:16px} .chip{border:1px solid var(--line);border-radius:20px;padding:8px 14px;font-size:12px;color:var(--dim);display:flex;align-items:center;gap:7px} </style><div class=\"screen\"><div style=\"display:flex;align-items:center;gap:14px;margin-bottom:20px\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dim)\" stroke-width=\"1.9\"><path d=\"M15 5l-7 7 7 7\"/></svg><div class=\"disp\" style=\"font-size:18px;font-weight:700\">スポーツ連動</div></div><!-- weekly cardio gauge --><div class=\"card\" style=\"padding:18px 18px 16px;margin-bottom:18px\"><div style=\"display:flex;justify-content:space-between;align-items:baseline;margin-bottom:4px\"><span style=\"font-size:13px;font-weight:700\">今週の有酸素</span><span class=\"disp\" style=\"font-size:14px;font-weight:800\"><span style=\"color:var(--teal)\">210</span><span style=\"font-size:11px;color:var(--faint)\"> / 150〜300分</span></span></div><div style=\"font-size:11px;color:var(--faint);margin-bottom:14px\">スポーツも活動時間として合算されます</div><!-- stacked bar --><div style=\"display:flex;height:12px;border-radius:6px;overflow:hidden;background:#26262C\"><div style=\"width:33%;background:var(--teal)\"></div><div style=\"width:29%;background:var(--gold)\"></div><div style=\"width:15%;background:var(--amber)\"></div></div><div style=\"display:flex;gap:16px;margin-top:12px;font-size:11px;color:var(--dim);flex-wrap:wrap\"><span style=\"display:flex;align-items:center;gap:6px\"><span style=\"width:9px;height:9px;border-radius:2px;background:var(--teal)\"></span>ランニング 70分</span><span style=\"display:flex;align-items:center;gap:6px\"><span style=\"width:9px;height:9px;border-radius:2px;background:var(--gold)\"></span>テニス 90分</span><span style=\"display:flex;align-items:center;gap:6px\"><span style=\"width:9px;height:9px;border-radius:2px;background:var(--amber)\"></span>ゴルフ 50分</span></div></div><!-- add sport chips --><div style=\"font-size:12px;color:var(--faint);margin:0 2px 10px\">スポーツを記録</div><div style=\"display:flex;flex-wrap:wrap;gap:9px;margin-bottom:20px\"><div class=\"chip\" style=\"border-color:rgba(203,163,90,.5);color:var(--gold)\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M5 5c4 3 5 11 2 14M19 5c-4 3-5 11-2 14\"/></svg>テニス</div><div class=\"chip\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><circle cx=\"12\" cy=\"7\" r=\"3\"/><path d=\"M12 10v7M12 17l6 4M9 21l3-4\"/></svg>ゴルフ</div><div class=\"chip\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M3 12c5-2 13-2 18 0M12 3c-3 4-3 14 0 18\"/></svg>バレー</div><div class=\"chip\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M13 4l-2 8h5l-7 8 2-8H9z\"/></svg>ランニング</div><div class=\"chip\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M3 14c3 2 5-2 8 0s5 2 8 0M3 18c3 2 5-2 8 0s5 2 8 0\"/><circle cx=\"16\" cy=\"7\" r=\"2\"/></svg>水泳</div></div><!-- this week log --><div style=\"font-size:12px;color:var(--faint);margin:0 2px 10px\">今週の記録</div><div class=\"card\" style=\"padding:6px 4px;margin-bottom:18px\"><div style=\"display:flex;align-items:center;gap:13px;padding:13px 14px\"><div style=\"width:38px;height:38px;border-radius:11px;background:rgba(203,163,90,.14);display:flex;align-items:center;justify-content:center;color:var(--gold);flex:none\"><svg width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M5 5c4 3 5 11 2 14M19 5c-4 3-5 11-2 14\"/></svg></div><div style=\"flex:1\"><div style=\"font-size:13.5px;font-weight:700\">テニス ・ 試合</div><div style=\"font-size:11px;color:var(--faint);margin-top:2px\">日 ・ 90分 ・ 右肩/体幹 高負荷</div></div><span style=\"font-size:10.5px;color:var(--teal);border:1px solid rgba(95,176,165,.4);padding:4px 8px;border-radius:7px\">有酸素+90</span></div><div style=\"height:1px;background:var(--line);margin:0 14px\"></div><div style=\"display:flex;align-items:center;gap:13px;padding:13px 14px\"><div style=\"width:38px;height:38px;border-radius:11px;background:rgba(219,150,90,.14);display:flex;align-items:center;justify-content:center;color:var(--amber);flex:none\"><svg width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><circle cx=\"12\" cy=\"7\" r=\"3\"/><path d=\"M12 10v7M12 17l6 4M9 21l3-4\"/></svg></div><div style=\"flex:1\"><div style=\"font-size:13.5px;font-weight:700\">ゴルフ ・ ラウンド</div><div style=\"font-size:11px;color:var(--faint);margin-top:2px\">土 ・ 50分換算 ・ 回旋系</div></div><span style=\"font-size:10.5px;color:var(--teal);border:1px solid rgba(95,176,165,.4);padding:4px 8px;border-radius:7px\">有酸素+50</span></div></div><div class=\"card\" style=\"padding:14px 15px;display:flex;gap:11px;align-items:flex-start;border-color:rgba(203,163,90,.28)\"><svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--gold)\" stroke-width=\"1.8\" style=\"flex:none;margin-top:1px\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 8v5M12 16v.3\"/></svg><div style=\"font-size:11.5px;color:var(--dim);line-height:1.65\">記録したスポーツの<b style=\"color:var(--tx)\">酷使部位</b>は、翌日の筋トレメニューの疲労管理に自動で反映されます。</div></div></div></body></html>"},{"id":"fatigue","title":"疲労管理","html":"<!doctype html><html><head><meta charset=\"utf-8\"></head><body><style> @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;500;700&family=Zen+Kaku+Gothic+New:wght@500;700;900&display=swap'); :root{ --bg:#0B0B0D; --surface:#151519; --surface2:#1E1E24; --line:rgba(255,255,255,.07); --tx:#ECECEA; --dim:#9A9AA2; --faint:#63636B; --gold:#CBA35A; --teal:#5FB0A5; --amber:#DB965A; --red:#D26A60; } *{box-sizing:border-box} body{margin:0;font-family:'Noto Sans JP',system-ui,sans-serif;background:var(--bg);color:var(--tx);-webkit-font-smoothing:antialiased} .disp{font-family:'Zen Kaku Gothic New','Noto Sans JP',sans-serif} a{color:var(--gold)} a:hover{color:#dcb877} .screen{width:390px;min-height:960px;position:relative; background:radial-gradient(130% 50% at 50% -6%, #1C161A 0%, #0B0B0D 52%);padding:24px 20px 40px} .card{background:var(--surface);border:1px solid var(--line);border-radius:16px} </style><div class=\"screen\"><div style=\"display:flex;align-items:center;gap:14px;margin-bottom:20px\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dim)\" stroke-width=\"1.9\"><path d=\"M15 5l-7 7 7 7\"/></svg><div class=\"disp\" style=\"font-size:18px;font-weight:700\">部位別 疲労管理</div></div><!-- body map --><div class=\"card\" style=\"padding:18px 16px;margin-bottom:16px;display:flex;gap:16px;align-items:center\"><div style=\"flex:none\"><svg width=\"104\" height=\"200\" viewBox=\"0 0 104 200\"><!-- head --><circle cx=\"52\" cy=\"18\" r=\"12\" fill=\"none\" stroke=\"#3A3A42\" stroke-width=\"2\"/><!-- torso --><path d=\"M34 34 L70 34 L66 96 L38 96 Z\" fill=\"#1E1E24\" stroke=\"#3A3A42\" stroke-width=\"2\"/><!-- shoulders (right highlighted = viewer left) --><circle cx=\"32\" cy=\"40\" r=\"9\" fill=\"rgba(210,106,96,.28)\" stroke=\"var(--red)\" stroke-width=\"2\"/><circle cx=\"72\" cy=\"40\" r=\"9\" fill=\"none\" stroke=\"#3A3A42\" stroke-width=\"2\"/><!-- core highlighted --><rect x=\"40\" y=\"60\" width=\"24\" height=\"30\" rx=\"6\" fill=\"rgba(219,150,90,.24)\" stroke=\"var(--amber)\" stroke-width=\"2\"/><!-- arms --><path d=\"M30 46 L22 92\" stroke=\"#3A3A42\" stroke-width=\"6\" stroke-linecap=\"round\"/><path d=\"M74 46 L82 92\" stroke=\"#3A3A42\" stroke-width=\"6\" stroke-linecap=\"round\"/><!-- legs --><path d=\"M44 98 L40 168\" stroke=\"#3A3A42\" stroke-width=\"8\" stroke-linecap=\"round\"/><path d=\"M60 98 L64 168\" stroke=\"#3A3A42\" stroke-width=\"8\" stroke-linecap=\"round\"/></svg></div><div style=\"flex:1;display:flex;flex-direction:column;gap:12px\"><div><div style=\"display:flex;justify-content:space-between;font-size:12px;margin-bottom:6px\"><span style=\"font-weight:700\">右肩</span><span style=\"color:var(--red)\">疲労 高</span></div><div style=\"height:6px;background:#26262C;border-radius:3px\"><div style=\"width:88%;height:100%;background:var(--red);border-radius:3px\"></div></div></div><div><div style=\"display:flex;justify-content:space-between;font-size:12px;margin-bottom:6px\"><span style=\"font-weight:700\">体幹</span><span style=\"color:var(--amber)\">疲労 中</span></div><div style=\"height:6px;background:#26262C;border-radius:3px\"><div style=\"width:64%;height:100%;background:var(--amber);border-radius:3px\"></div></div></div><div><div style=\"display:flex;justify-content:space-between;font-size:12px;margin-bottom:6px\"><span style=\"font-weight:700\">胸</span><span style=\"color:var(--teal)\">回復 済</span></div><div style=\"height:6px;background:#26262C;border-radius:3px\"><div style=\"width:22%;height:100%;background:var(--teal);border-radius:3px\"></div></div></div><div><div style=\"display:flex;justify-content:space-between;font-size:12px;margin-bottom:6px\"><span style=\"font-weight:700\">脚</span><span style=\"color:var(--teal)\">回復 済</span></div><div style=\"height:6px;background:#26262C;border-radius:3px\"><div style=\"width:18%;height:100%;background:var(--teal);border-radius:3px\"></div></div></div></div></div><!-- alert --><div class=\"card\" style=\"padding:15px 16px;margin-bottom:18px;border-color:rgba(219,150,90,.4);background:linear-gradient(180deg,rgba(219,150,90,.10),var(--surface));display:flex;gap:11px;align-items:flex-start\"><div style=\"width:30px;height:30px;border-radius:9px;background:rgba(219,150,90,.18);display:flex;align-items:center;justify-content:center;color:var(--amber);flex:none;margin-top:1px\"><svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\"><path d=\"M12 3l9 16H3z\"/><path d=\"M12 9v4M12 16v.3\"/></svg></div><div style=\"font-size:11.5px;color:var(--dim);line-height:1.65\">週末のテニス（片手バックハンド）で<b style=\"color:var(--tx)\">右肩・体幹</b>を酷使。オーバートレーニング防止のため、明日のメニューを<b style=\"color:var(--tx)\">安全なマシン種目</b>に自動調整しました。</div></div><!-- menu swap --><div style=\"font-size:12px;color:var(--faint);margin:0 2px 10px\">明日のメニュー ・ 自動調整</div><div class=\"card\" style=\"padding:6px 4px;margin-bottom:18px\"><div style=\"display:flex;align-items:center;gap:11px;padding:13px 14px\"><div style=\"flex:1;font-size:12.5px;color:var(--faint);text-decoration:line-through\">ダンベルショルダープレス</div><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--faint)\" stroke-width=\"2\" style=\"flex:none\"><path d=\"M5 12h13M13 6l6 6-6 6\"/></svg><div style=\"flex:1;font-size:12.5px;font-weight:700;text-align:right\">マシンショルダープレス</div></div><div style=\"height:1px;background:var(--line);margin:0 14px\"></div><div style=\"display:flex;align-items:center;gap:11px;padding:13px 14px\"><div style=\"flex:1;font-size:12.5px;color:var(--faint);text-decoration:line-through\">バーベルロー</div><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--faint)\" stroke-width=\"2\" style=\"flex:none\"><path d=\"M5 12h13M13 6l6 6-6 6\"/></svg><div style=\"flex:1;font-size:12.5px;font-weight:700;text-align:right\">シーテッドマシンロー</div></div><div style=\"height:1px;background:var(--line);margin:0 14px\"></div><div style=\"display:flex;align-items:center;gap:11px;padding:13px 14px\"><div style=\"flex:1;font-size:12.5px;color:var(--faint);text-decoration:line-through\">アブローラー (体幹)</div><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--faint)\" stroke-width=\"2\" style=\"flex:none\"><path d=\"M5 12h13M13 6l6 6-6 6\"/></svg><div style=\"flex:1;font-size:12.5px;font-weight:700;text-align:right;color:var(--teal)\">本日はスキップ</div></div></div><div style=\"font-size:11px;color:var(--faint);text-align:center;line-height:1.7\"> フリーウェイトより関節への負担が少ないマシン種目で<br>刺激を維持しつつ、酷使部位を回復させます。 </div></div></body></html>"}];
